/**  The same app on Flathub, which installs better than a `.deb` file can. */
export type OnFlathub = {
	id: string,
	name: string,
	summary: string | null,
	icon: string | null,
	verified: boolean,
};

export type OpenedFile = { kind: "flatpakRef"; path: string; id: string; title: string; branch: string | null; url: string; runtime: boolean; summary: string | null; homepage: string | null; icon: string | null } | { kind: "flatpakBundle"; path: string; id: string; title: string; branch: string; summary: string | null; icon: string | null; size: number; runtime: string | null; origin: string | null } | { kind: "flatpakRepo"; path: string; name: string; title: string; url: string; summary: string | null; homepage: string | null } | { kind: "package"; path: string; package: string; version: string; summary: string; description: string; license: string; homepage: string | null; size: number; installed: boolean; system: boolean; desktop: string | null; repository: CheckedSource | null; repositoryError: string | null; verified: boolean } | { kind: "deb"; path: string; package: string; name: string; version: string; summary: string; description: string; homepage: string | null; size: number; icon: string | null; installed: boolean; runsHere: boolean; flathub: OnFlathub | null } | { kind: "appImage"; path: string; name: string; summary: string | null; version: string | null; icon: string | null; size: number; 
/**  What it declared it needs, for a Sabine app. */
permissions: Permissions | null; 
/**  Why it asks to run outside a sandbox, when it does. */
unsandboxed: string | null };

export type Operation = {
	id: number,
	key: string,
	members: string[],
	title: string,
	action: Action,
	state: OperationState,
	progress: Progress | null,
	error: string | null,
};

export type OperationState = "queued" | "running" | "failed";

export type Palette = {
	accent: string,
	wallpaperAccent: string,
	pureBlack: boolean,
	colors: SchemeColors,
	terminal: SchemeColors,
	appIcons: AppIcons,
	taskbar: import("@luft/ui").TaskbarLooks,
};

export type Permissions = {
	shared: string[],
	sockets: string[],
	devices: string[],
	filesystems: string[],
	sessionBus: string[],
	systemBus: string[],
};

export type Progress = {
	stage: Stage,
	fraction: number | null,
};

/**
 *  A repository file and the keys it names, by the address `gpgkey` gives each, ready to be
 *  checked and added.
 */
export type RepositoryDraft = {
	file: string,
	text: string,
	keys: { [key in string]: string },
};

/**
 *  What an installed AppImage's sandbox opens to it, and why it asked to run
 *  without one, if it did.
 */
export type Sandbox = {
	permissions: Permissions,
	unsandboxed: string | null,
};

export type SchemeColors = {
	light: { [key in string]: string },
	dark: { [key in string]: string },
};

export type Setting = { setting: "allowed"; value: boolean } | { setting: "banners"; value: boolean } | { setting: "lockScreen"; value: boolean } | { setting: "detailsOnLockScreen"; value: boolean } | { setting: "sound"; value: string } | { setting: "duringDoNotDisturb"; value: string } | { setting: "keptInList"; value: boolean };

export type Source = "flatpak" | "appImage" | "tool" | "debian" | "system";

export type SourceKey = {
	fingerprint: string,
	user: string,
};

export type Stage = "waiting" | "preparing" | "downloading" | "installing" | "removing" | "finishing";

export type ToolSummary = {
	package: string,
	summary: string,
};

export type Typography = {
	interface: string | null,
	monospace: string | null,
	textScale: number,
};

export type Updates = {
	apps: AppUpdate[],
	checked: number,
	error: string | null,
};
